import contextlib
import io
import unittest
from unittest import mock

from textkit.cli import main
from textkit.mdtable import to_markdown


def run_with_stdin(text, *argv):
    out, err = io.StringIO(), io.StringIO()
    with mock.patch("sys.stdin", io.StringIO(text)), \
            contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class ToMarkdownTest(unittest.TestCase):
    def test_builds_header_separator_and_rows(self):
        self.assertEqual(to_markdown([["a", "b"], ["1", "2"], ["3", "4"]]),
                         "| a | b |\n| --- | --- |\n| 1 | 2 |\n| 3 | 4 |")

    def test_header_only(self):
        self.assertEqual(to_markdown([["a"]]), "| a |\n| --- |")

    def test_strips_cells(self):
        self.assertEqual(to_markdown([[" a ", "\tb\n"], [" 1 ", "2  "]]),
                         "| a | b |\n| --- | --- |\n| 1 | 2 |")

    def test_escapes_pipes(self):
        self.assertEqual(to_markdown([["a|b", "c"], ["|", "x | y"]]),
                         "| a\\|b | c |\n| --- | --- |\n| \\| | x \\| y |")

    def test_no_rows_raises(self):
        with self.assertRaises(ValueError):
            to_markdown([])

    def test_empty_header_raises(self):
        with self.assertRaises(ValueError):
            to_markdown([[]])

    def test_empty_header_with_data_raises(self):
        with self.assertRaises(ValueError):
            to_markdown([[], ["1"]])

    def test_ragged_rows_raise(self):
        with self.assertRaises(ValueError):
            to_markdown([["a", "b"], ["1"]])
        with self.assertRaises(ValueError):
            to_markdown([["a", "b"], ["1", "2", "3"]])
        with self.assertRaises(ValueError):
            to_markdown([["a", "b"], []])


class MdtableCommandTest(unittest.TestCase):
    def test_reads_csv_from_stdin(self):
        self.assertEqual(run_with_stdin("a,b\n1,2\n", "mdtable"),
                         (0, "| a | b |\n| --- | --- |\n| 1 | 2 |\n", ""))

    def test_quoted_csv_fields(self):
        code, out, _ = run_with_stdin('name,note\n"Smith, J","say ""hi"""\n', "mdtable")
        self.assertEqual(code, 0)
        self.assertEqual(out, '| name | note |\n| --- | --- |\n| Smith, J | say "hi" |\n')

    def test_ragged_csv_exits_2_with_error(self):
        code, out, err = run_with_stdin("a,b\n1\n", "mdtable")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

    def test_empty_stdin_exits_2_with_error(self):
        code, out, err = run_with_stdin("", "mdtable")
        self.assertEqual(code, 2)
        self.assertTrue(err.startswith("error: "))

    def test_listed_in_commands(self):
        _, out, _ = run_with_stdin("", "commands")
        self.assertIn("mdtable", out.split())


if __name__ == "__main__":
    unittest.main()
"""Render rows of text as a GitHub markdown table."""


def _line(cells):
    return "| " + " | ".join(cells) + " |"


def _cell(text):
    return text.strip().replace("|", "\\|")


def to_markdown(rows):
    """Render rows (header first) as a markdown table with no trailing newline.

    Raises ValueError for no rows, an empty header, or a row whose length differs from the header.
    """
    if not rows:
        raise ValueError("no rows")
    header = rows[0]
    if not header:
        raise ValueError("empty header")
    width = len(header)
    for number, row in enumerate(rows[1:], start=2):
        if len(row) != width:
            raise ValueError(f"row {number} has {len(row)} cells, expected {width}")
    lines = [_line(_cell(c) for c in header), _line(["---"] * width)]
    lines += [_line(_cell(c) for c in row) for row in rows[1:]]
    return "\n".join(lines)

